const VENMO_URL = "https://venmo.com/u/Blazevaultcards";
const CASHAPP_URL = "https://cash.app/$Blazevaultcards";
const ZELLE_QR_IMAGE = "data:image/jpeg;base64,";
const IG_HANDLE = "blazevaultcards";
const DISCORD_URL = "https://discord.gg/qKZhGbNq5";
const IG_URL = `https://instagram.com/${IG_HANDLE}`;

