const RARITY_STYLES = {
  common: { label: "Common", accent: "#8A8F98" },
  rare: { label: "Rare", accent: "#D4AF6A" },
  holo: { label: "Holo Rare", accent: "#FF2E3E" },
};

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function CardTile({ item, onToggleSold, adminMode }) {
  const [hover, setHover] = useState(false);
  const rarity = RARITY_STYLES[item.rarity] || RARITY_STYLES.common;

  return (
    <div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        position: "relative",
        borderRadius: 10,
        overflow: "hidden",
        background: "#141416",
        border: "1px solid #2B1416",
        opacity: item.sold ? 0.4 : 1,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `linear-gradient(115deg, transparent 30%, ${rarity.accent}33 45%, #8C101333 55%, transparent 70%)`,
          transform: hover ? "translateX(20%)" : "translateX(-120%)",
          transition: "transform 0.6s ease",
          pointerEvents: "none",
        }}
      />
      <div style={{ aspectRatio: "3/4", background: "#0F1015", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
        {item.image ? (
          <img src={item.image} alt={item.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <Sparkles size={28} color="#3A3C48" />
        )}
      </div>
      <div style={{ padding: "12px 14px 14px" }}>
        <div style={{ fontFamily: "Inter", fontWeight: 600, fontSize: 14, color: "#EDE6D6", lineHeight: 1.25 }}>{item.name}</div>
        <div style={{ fontFamily: "JetBrains Mono", fontSize: 11, color: rarity.accent, marginTop: 3 }}>{rarity.label}</div>

        <div style={{ marginTop: 10, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
          <span style={{ fontFamily: "JetBrains Mono", fontSize: 11, color: "#6B6E7A" }}>
            {item.sold ? "SOLD" : item.priceNote || "DM for price"}
          </span>
          {adminMode ? (
            <button
              onClick={() => onToggleSold(item.id)}
              style={{
                fontFamily: "Inter", fontWeight: 600, fontSize: 11, padding: "6px 10px", borderRadius: 6,
                border: "1px solid #2B1416", cursor: "pointer",
                background: item.sold ? "#2B1416" : "none", color: "#EDE6D6",
                display: "flex", alignItems: "center", gap: 4,
              }}
            >
              {item.sold ? "Mark available" : <>Mark sold</>}
            </button>
          ) : (
            <a
              href={IG_URL}
              target="_blank"
              rel="noopener noreferrer"
              style={{
                fontFamily: "Inter", fontWeight: 600, fontSize: 12, padding: "6px 12px", borderRadius: 6,
                textDecoration: "none",
                pointerEvents: item.sold ? "none" : "auto",
                background: item.sold ? "#2B1416" : "linear-gradient(90deg,#FF2E3E,#8C1013)",
                color: item.sold ? "#6B6E7A" : "#0F1015",
              }}
            >
              DM to buy
            </a>
          )}
        </div>
      </div>
    </div>
  );
}

function AddItemForm({ onAdd, onClose }) {
  const [name, setName] = useState("");
  const [priceNote, setPriceNote] = useState("");
  const [rarity, setRarity] = useState("rare");
  const [image, setImage] = useState(null);
  const fileRef = useRef(null);

  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setImage(reader.result);
    reader.readAsDataURL(file);
  }

  function submit() {
    if (!name.trim()) return;
    onAdd({ id: uid(), name: name.trim(), priceNote: priceNote.trim(), rarity, image, sold: false });
    onClose();
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "#00000099", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }}>
      <div style={{ background: "#141416", border: "1px solid #2B1416", borderRadius: 12, padding: 24, width: 340, maxWidth: "90vw" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <span style={{ fontFamily: "Anton", fontSize: 20, color: "#EDE6D6", letterSpacing: 0.5 }}>ADD LISTING</span>
          <X size={18} color="#6B6E7A" style={{ cursor: "pointer" }} onClick={onClose} />
        </div>

        <div
          onClick={() => fileRef.current?.click()}
          style={{ height: 100, borderRadius: 8, border: "1px dashed #3A3C48", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", marginBottom: 12, overflow: "hidden", background: "#0F1015" }}
        >
          {image ? <img src={image} alt="" style={{ height: "100%" }} /> : <Upload size={20} color="#6B6E7A" />}
        </div>
        <input ref={fileRef} type="file" accept="image/*" onChange={handleFile} style={{ display: "none" }} />

        <input placeholder="Card name" value={name} onChange={(e) => setName(e.target.value)} style={inputStyle} />
        <input placeholder="Price note (e.g. '$40 obo') — optional" value={priceNote} onChange={(e) => setPriceNote(e.target.value)} style={inputStyle} />

        <select value={rarity} onChange={(e) => setRarity(e.target.value)} style={{ ...inputStyle, marginBottom: 14 }}>
          <option value="common">Common</option>
          <option value="rare">Rare</option>
          <option value="holo">Holo Rare</option>
        </select>

        <button onClick={submit} style={{ width: "100%", padding: "10px 0", borderRadius: 6, border: "none", background: "linear-gradient(90deg,#FF2E3E,#8C1013)", color: "#0F1015", fontFamily: "Inter", fontWeight: 700, cursor: "pointer" }}>
          Add to catalog
        </button>
      </div>
    </div>
  );
}

const inputStyle = {
  width: "100%",
  padding: "9px 10px",
  marginBottom: 10,
  borderRadius: 6,
  border: "1px solid #2B1416",
  background: "#0F1015",
  color: "#EDE6D6",
  fontFamily: "Inter",
  fontSize: 13,
  outline: "none",
  boxSizing: "border-box",
};

function LoginModal({ onClose }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function submit() {
    setError("");
    setLoading(true);
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    setLoading(false);
    if (error) {
      setError("Wrong email or password.");
      return;
    }
    onClose();
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "#00000099", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 60 }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{ background: "#141416", border: "1px solid #2B1416", borderRadius: 12, padding: 24, width: 320, maxWidth: "90vw" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <span style={{ fontFamily: "Anton", fontSize: 20, color: "#EDE6D6", letterSpacing: 0.5 }}>ADMIN LOGIN</span>
          <X size={18} color="#6B6E7A" style={{ cursor: "pointer" }} onClick={onClose} />
        </div>
        <input placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} style={inputStyle} />
        <input placeholder="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} style={inputStyle} onKeyDown={(e) => e.key === "Enter" && submit()} />
        {error && <div style={{ color: "#FF2E3E", fontSize: 12, marginBottom: 10, fontFamily: "Inter" }}>{error}</div>}
        <button
          onClick={submit}
          disabled={loading}
          style={{ width: "100%", padding: "10px 0", borderRadius: 6, border: "none", background: "linear-gradient(90deg,#FF2E3E,#8C1013)", color: "#0F1015", fontFamily: "Inter", fontWeight: 700, cursor: "pointer" }}
        >
          {loading ? "Signing in…" : "Log in"}
        </button>
      </div>
    </div>
  );
}

