export default function TCGStorefront() {
  const [items, setItems] = useState([]);
  const [adminMode, setAdminMode] = useState(false);
  const [session, setSession] = useState(null);
  const [showLogin, setShowLogin] = useState(false);
  const [showAddForm, setShowAddForm] = useState(false);
  const [showPayments, setShowPayments] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    (async () => {
      const seed = [
        { id: uid(), name: "Charizard ex — Alt Art", priceNote: "$180 obo", rarity: "holo", image: null, sold: false },
        { id: uid(), name: "Blue-Eyes White Dragon", priceNote: "$25", rarity: "rare", image: null, sold: false },
        { id: uid(), name: "Booster Box — Scarlet & Violet", priceNote: "DM for price", rarity: "common", image: null, sold: false },
      ];

      let current = seed;
      try {
        let cat = null;
        try { cat = await storage.get("catalog", true); } catch (e) {}
        if (cat && cat.value) {
          try {
            const parsed = JSON.parse(cat.value);
            if (Array.isArray(parsed)) current = parsed;
          } catch (e) {}
        }
      } catch (e) {}

      try {
        let importFlag = null;
        try { importFlag = await storage.get("bulk_import_v1_done", true); } catch (e) {}
        if (!importFlag) {
          const existingIds = new Set(current.map((it) => it.id));
          const toAdd = BULK_IMPORT_V1.filter((it) => !existingIds.has(it.id));
          current = [...toAdd, ...current];
          try { await storage.set("bulk_import_v1_done", "true", true); } catch (e) {}
        }
      } catch (e) {}

      setItems(current);

      try { await storage.set("catalog", JSON.stringify(current), true); } catch (e) {}

      setLoaded(true);
    })();
  }, []);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data: listener } = supabase.auth.onAuthStateChange((_event, newSession) => {
      setSession(newSession);
      if (!newSession) setAdminMode(false);
    });
    return () => listener.subscription.unsubscribe();
  }, []);

  async function persistCatalog(next) {
    setItems(next);
    try { await storage.set("catalog", JSON.stringify(next), true); } catch (e) { console.error(e); }
  }

  function addListing(item) {
    persistCatalog([item, ...items]);
  }
  function toggleSold(id) {
    persistCatalog(items.map((it) => (it.id === id ? { ...it, sold: !it.sold } : it)));
  }
  function copyHandle() {
    navigator.clipboard?.writeText(`@${IG_HANDLE}`);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  }

  if (!loaded) return <div style={{ background: "#0F1015", height: "100vh" }} />;

  return (
    <div style={{ minHeight: "100vh", background: "#0F1015", fontFamily: "Inter" }}>
      <style>{FONT_IMPORT}</style>

      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "18px 24px", borderBottom: "1px solid #141416", position: "sticky", top: 0, background: "#0F1015", zIndex: 10 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <img src={LOGO_IMAGE} alt="Blaze's Vault" style={{ height: 40, width: 40, borderRadius: 6, objectFit: "cover" }} />
          <div style={{ fontFamily: "Anton", fontSize: 26, color: "#EDE6D6", letterSpacing: 1 }}>BLAZE'S VAULT</div>
        </div>
        <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
          <button onClick={() => (session ? setAdminMode((a) => !a) : setShowLogin(true))} style={{ background: "none", border: "none", cursor: "pointer", color: adminMode ? "#FF2E3E" : "#6B6E7A" }}>
            <Settings size={19} />
          </button>
          <a href={IG_URL} target="_blank" rel="noopener noreferrer" style={{ display: "flex", alignItems: "center", gap: 6, textDecoration: "none", color: "#EDE6D6", border: "1px solid #2B1416", borderRadius: 6, padding: "6px 12px", fontSize: 13, fontFamily: "Inter", fontWeight: 600 }}>
            <Instagram size={15} /> @{IG_HANDLE}
          </a>
        </div>
      </header>

      <div
        style={{
          margin: "20px 24px",
          borderRadius: 12,
          padding: "18px 20px",
          background: "linear-gradient(100deg, #1C1D2E, #141416 60%)",
          border: "1px solid #2B1416",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 16,
          flexWrap: "wrap",
        }}
      >
        <div>
          <div style={{ fontFamily: "Inter", fontWeight: 600, fontSize: 14, color: "#EDE6D6" }}>Every card here is DM-only.</div>
          <div style={{ fontFamily: "Inter", fontSize: 13, color: "#8A8F98", marginTop: 3 }}>
            Tap "DM to buy" or message <span style={{ color: "#FF2E3E" }}>@{IG_HANDLE}</span> directly to lock in pricing and pay.
          </div>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <a href={IG_URL} target="_blank" rel="noopener noreferrer" style={{ display: "flex", alignItems: "center", gap: 6, textDecoration: "none", padding: "9px 16px", borderRadius: 6, background: "linear-gradient(90deg,#FF2E3E,#8C1013)", color: "#0F1015", fontWeight: 700, fontSize: 13 }}>
            <Instagram size={15} /> Open Instagram
          </a>
          <button onClick={copyHandle} style={{ padding: "9px 14px", borderRadius: 6, border: "1px solid #2B1416", background: "none", color: "#EDE6D6", fontSize: 13, cursor: "pointer", display: "flex", alignItems: "center", gap: 6 }}>
            {copied ? <><Check size={14} color="#FF2E3E" /> Copied</> : "Copy handle"}
          </button>
          <button onClick={() => setShowPayments(true)} style={{ padding: "9px 14px", borderRadius: 6, border: "1px solid #2B1416", background: "none", color: "#EDE6D6", fontSize: 13, cursor: "pointer", display: "flex", alignItems: "center", gap: 6 }}>
            <Wallet size={15} /> Payment options
          </button>
          <a href={DISCORD_URL} target="_blank" rel="noopener noreferrer" style={{ display: "flex", alignItems: "center", gap: 6, textDecoration: "none", padding: "9px 14px", borderRadius: 6, border: "1px solid #2B1416", background: "none", color: "#EDE6D6", fontSize: 13, fontFamily: "Inter", fontWeight: 600 }}>
            <MessageCircle size={15} /> Join Discord
          </a>
        </div>
      </div>

      {adminMode && (
        <div style={{ padding: "14px 24px", borderBottom: "1px solid #141416", display: "flex", justifyContent: "space-between", alignItems: "center", background: "#0F0F11" }}>
          <span style={{ fontFamily: "JetBrains Mono", fontSize: 12, color: "#6B6E7A" }}>{items.length} listings · {items.filter((i) => !i.sold).length} available</span>
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setShowAddForm(true)} style={{ display: "flex", alignItems: "center", gap: 6, background: "none", border: "1px solid #2B1416", borderRadius: 6, padding: "6px 12px", color: "#EDE6D6", fontSize: 12, cursor: "pointer" }}>
              <Plus size={14} /> Add listing
            </button>
            <button onClick={() => supabase.auth.signOut()} style={{ background: "none", border: "1px solid #2B1416", borderRadius: 6, padding: "6px 12px", color: "#8A8F98", fontSize: 12, cursor: "pointer" }}>
              Log out
            </button>
          </div>
        </div>
      )}

      <div style={{ padding: "24px" }}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(160px, 1fr))", gap: 14 }}>
          {items.map((item) => (
            <CardTile key={item.id} item={item} onToggleSold={toggleSold} adminMode={adminMode} />
          ))}
        </div>
        {items.length === 0 && <div style={{ color: "#6B6E7A", fontSize: 13 }}>No listings yet — use the gear icon to add your first card.</div>}
      </div>

      {showAddForm && <AddItemForm onAdd={addListing} onClose={() => setShowAddForm(false)} />}
      {showPayments && <PaymentModal onClose={() => setShowPayments(false)} />}
      {showLogin && <LoginModal onClose={() => { setShowLogin(false); setAdminMode(true); }} />}
    </div>
  );
}
